/* ---------- Chrome, ověření věku ---------- */
function applyThemeChrome(){document.body.dataset.style='winery';const keys=['all','white','red','rose','sparkling','sale'];$$('.category-nav>a').forEach((a,i)=>{a.href='#catalog/'+keys[i];a.textContent=THEME.categories[keys[i]];});announcements.splice(0,announcements.length,`Doprava zdarma při nákupu nad ${currency(FREE)}`,'Dárkové balení zdarma ke každé objednávce','Ukázkový kód BRAVE5 · 5 % na první nákup','Degustace ve sklepě každý pátek a sobotu');$('#announcement-text').textContent=announcements[0];}
function ageGate(){if(read('brave-age',false))return;document.body.insertAdjacentHTML('beforeend',`<div class="age-gate" role="dialog" aria-modal="true" aria-labelledby="age-title"><div class="age-box"><img src="./assets/brave-winery-logo.svg" alt="Brave Winery" width="120"><p class="eyebrow">Ověření věku</p><h2 id="age-title">Je vám alespoň 18 let?</h2><p>Stránky obsahují informace o alkoholických nápojích. Víno prodáváme jen dospělým.</p><div class="age-actions"><button class="btn dark" data-action="age-yes">Ano, je mi 18+</button><button class="btn" data-action="age-no">Ne</button></div><p class="age-note" hidden>Omlouváme se, stránky jsou určené jen osobám starším 18 let.</p></div></div>`);document.documentElement.classList.add('is-locked');window.__lenis?.stop();}
window.updatePresetTitle=function(){if(!location.hash||['#home','#main'].includes(location.hash))document.title='Brave Winery — Vína ze srdce Moravy';};

/* ---------- Paralaxa úvodu (scroll + myš) ---------- */
const motionReduced=matchMedia('(prefers-reduced-motion: reduce)');let heroFrame=0,mx=0,my=0;
function paintHero(){heroFrame=0;const h=$('[data-parallax-hero]');if(!h||motionReduced.matches)return;const vh=innerHeight,y=Math.min(scrollY,vh*1.2),p=y/vh;
 h.style.setProperty('--bg-y',`${(y*.32).toFixed(1)}px`);h.style.setProperty('--bg-s',(1.06+p*.06).toFixed(4));h.style.setProperty('--fg-y',`${(y*.12).toFixed(1)}px`);h.style.setProperty('--fg-s',(1+p*.45).toFixed(4));h.style.setProperty('--cta-o',Math.max(0,1-p*2.2).toFixed(3));h.style.setProperty('--copy-y',`${(y*-.14).toFixed(1)}px`);h.style.setProperty('--copy-o',Math.max(0,1-p*3.2).toFixed(3));h.style.setProperty('--mx',mx.toFixed(3));h.style.setProperty('--my',my.toFixed(3));}
const reqHero=()=>{if(!heroFrame)heroFrame=requestAnimationFrame(paintHero)};
addEventListener('scroll',reqHero,{passive:true});addEventListener('resize',reqHero,{passive:true});
addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5;reqHero();},{passive:true});
window.setupScrollScenes=function(){const h=$('[data-parallax-hero]');if(h){h.classList.remove('is-ready');requestAnimationFrame(()=>requestAnimationFrame(()=>{h.classList.add('is-ready');$('h1[data-split]',h)?.classList.add('is-in')}));}reqHero();setupCatList();};


/* ---------- Mega menu: lahev jako čistý výřez s rytinou místo fotky s popiskem ---------- */
{const baseMega=megaPreview;megaPreview=function(name,label,href){const box=$('#mega-menu .mega-image');baseMega(name,label,href);if(!box)return;
 let il=$('.mi-illus',box);if(!il){il=document.createElement('img');il.className='mi-illus';il.alt='';il.setAttribute('aria-hidden','true');box.prepend(il);}
 clearTimeout(box._b);box._b=setTimeout(()=>{const b=/^b-/.test(name||'');box.classList.toggle('is-bottle',b);if(b)il.src='./assets/m/'+name.replace(/^b-/,'i-')+'-s.webp';},140);};}
/* ---------- Seznam kategorií s obrázkem u kurzoru ---------- */
function setupCatList(){const list=$('[data-cat-list]');if(!list)return;const fl=$('.cat-float',list.parentElement),ims=$$('.cf-w',fl);let tick=0;let tx=0,ty=0,cx=0,cy=0,raf=0;const loop=()=>{cx+=(tx-cx)*.14;cy+=(ty-cy)*.14;fl.style.transform=`translate3d(${cx}px,${cy}px,0) translate(-50%,-50%)`;raf=Math.abs(tx-cx)+Math.abs(ty-cy)>.3?requestAnimationFrame(loop):0;};
 list.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=list.parentElement.getBoundingClientRect();tx=e.clientX-r.left;ty=e.clientY-r.top;if(!raf)raf=requestAnimationFrame(loop);});
 $$('a[data-cat-img]',list).forEach(a=>a.addEventListener('pointerenter',()=>{const n=a.dataset.catImg;const grp=ims.filter(w=>w.dataset.cat===n);let k=0;const show=()=>ims.forEach(w=>w.classList.toggle('show',w===grp[k%grp.length]));show();clearInterval(tick);if(grp.length>1)tick=setInterval(()=>{k++;show();},1300);fl.classList.add('on');list.classList.add('hovering');a.classList.add('active');}));
 $$('a[data-cat-img]',list).forEach(a=>a.addEventListener('pointerleave',()=>a.classList.remove('active')));
 list.addEventListener('pointerleave',()=>{clearInterval(tick);fl.classList.remove('on');list.classList.remove('hovering');});}

/* ---------- Akce: taby vín, kvíz, věk, rezervace ---------- */
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='wine-tab'){wineTab=el.dataset.tab;$$('[data-action="wine-tab"]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-selected',b===el)});const r=$('#wine-rail');r.innerHTML=products.filter(p=>p.category===wineTab).map(card).join('');r.scrollLeft=0;window.refreshRails?.();}
 if(a==='quiz-answer'){quiz.answers[quiz.step]=el.dataset.value;quiz.step++;$('.quiz-box').innerHTML=quizInner();}
 if(a==='quiz-back'){quiz.step=Math.max(0,quiz.step-1);$('.quiz-box').innerHTML=quizInner();}
 if(a==='quiz-reset'){quiz={step:0,answers:[]};$('.quiz-box').innerHTML=quizInner();}
 if(a==='age-yes'){localStorage.setItem('brave-age','true');$('.age-gate')?.remove();document.documentElement.classList.remove('is-locked');window.__lenis?.start();}
 if(a==='age-no'){$('.age-note').hidden=false;}
});
function bookingSum(form){const opt=$('input[name="option"]:checked',form),pr=Number(opt?.dataset.price||0),persons=Number(form.persons?.value||1);if(form.dataset.kind==='tasting')return {text:`${persons} × ${currency(pr)} = <b>${currency(pr*persons)}</b>`,total:pr*persons};const a=new Date(form.from.value),b=new Date(form.to.value);const nights=Math.max(0,Math.round((b-a)/864e5));if(!form.to.value||nights<1)return {text:'Vyberte datum odjezdu.',total:0};const busy=[...Array(nights)].some((_,i)=>new Date(a.getTime()+i*864e5).getDay()===6&&a.getDate()%2===0);return {text:busy?'V tomto termínu je pokoj obsazený (ukázka). Zkuste jiný termín.':`${nights} ${nights===1?'noc':nights<5?'noci':'nocí'} × ${currency(pr)} = <b>${currency(pr*nights)}</b> · snídaně v ceně · <span class="ok">volno</span>`,total:busy?0:pr*nights,busy};}
document.addEventListener('input',e=>{const f=e.target.closest('form[data-form="booking"]');if(f)$('[data-booking-sum]',f).innerHTML=bookingSum(f).text;});
document.addEventListener('change',e=>{const f=e.target.closest('form[data-form="booking"]');if(f)$('[data-booking-sum]',f).innerHTML=bookingSum(f).text;});
document.addEventListener('submit',e=>{const f=e.target;if(f.dataset?.form!=='booking')return;e.preventDefault();e.stopImmediatePropagation();const s=bookingSum(f);if(f.dataset.kind==='room'&&(!s.total||s.busy)){toast('Vyberte prosím volný termín.');return;}const opt=$('input[name="option"]:checked',f);const label=$('b',opt.closest('label')).textContent;modal('Rezervace přijata.',`<div class="notice">Ukázka: nic se neodeslalo a termín se neblokuje.</div><p><b>${label}</b><br>${f.dataset.kind==='tasting'?`${f.date.value} v ${f.time.value} · ${f.persons.value} osob`:`${f.from.value} – ${f.to.value} · ${f.persons.value} osob`}</p><p>${s.text}</p><p class="muted">V napojeném systému dostanete potvrzení e-mailem a termín se zapíše do kalendáře vinařství.</p><button class="btn dark" data-action="close-modal">Rozumím</button>`);f.reset();},true);
document.addEventListener('focusin',e=>{const f=e.target.closest?.('form[data-form="booking"]');if(f&&!$('[data-booking-sum]',f).innerHTML)$('[data-booking-sum]',f).innerHTML=bookingSum(f).text;});

applyThemeChrome();render();ageGate();if(!read('brave-consent',null))$('#cookie-banner').hidden=false;

/* ---------- „Objevte všechna naše vína“: text se při scrollu posouvá doleva ---------- */
(()=>{let f=0;const paint=()=>{f=0;const el=document.querySelector('.pd-discover');if(!el||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect(),vh=innerHeight;if(r.bottom<0||r.top>vh)return;const p=Math.min(1,Math.max(0,(vh-r.top)/(vh+r.height)));el.style.setProperty('--dx',(p*-1).toFixed(4));};
 const req=()=>{if(!f)f=requestAnimationFrame(paint)};addEventListener('scroll',req,{passive:true});addEventListener('resize',req,{passive:true});addEventListener('hashchange',()=>setTimeout(req,300));})();

/* Vinné řady: připnutá sekce, stopa jede doleva podle scrollu */
(()=>{let f=0;const paint=()=>{f=0;const sec=document.querySelector('.series');if(!sec)return;const tr=sec.querySelector('.series-track');
 const desk=innerWidth>900&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!desk){sec.style.height='';tr.style.transform='';return;}
 const dist=Math.max(0,tr.scrollWidth-innerWidth),h=dist+innerHeight;if(sec._h!==h){sec._h=h;sec.style.height=h+'px';}
 const r=sec.getBoundingClientRect();const p=Math.min(1,Math.max(0,-r.top/Math.max(1,dist)));tr.style.transform='translate3d('+(-p*dist).toFixed(1)+'px,0,0)';};
 const req=()=>{if(!f)f=requestAnimationFrame(paint)};addEventListener('scroll',req,{passive:true});addEventListener('resize',()=>{const s=document.querySelector('.series');if(s)s._h=0;req()},{passive:true});
 addEventListener('hashchange',()=>setTimeout(()=>{const s=document.querySelector('.series');if(s)s._h=0;req()},300));addEventListener('load',req);setTimeout(req,600);})();

/* Patička: fotka v logu jede pomaleji než stránka */
(()=>{let f=0;const paint=()=>{f=0;const m=document.querySelector('.fw-mask');if(!m||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=m.getBoundingClientRect(),vh=innerHeight;if(r.bottom<0||r.top>vh)return;
 const p=(vh-r.top)/(vh+r.height);m.style.setProperty('--fy',((p-.5)*r.height*.55).toFixed(1)+'px');};
 const req=()=>{if(!f)f=requestAnimationFrame(paint)};addEventListener('scroll',req,{passive:true});addEventListener('resize',req,{passive:true});req();})();

