(()=>{const fit=()=>{const h=document.querySelector('.hero-parallax'),c=h&&h.querySelector('.hp-cta');if(c)h.style.setProperty('--cta-h',c.offsetHeight+'px');};
 addEventListener('resize',fit,{passive:true});addEventListener('hashchange',()=>setTimeout(fit,60));addEventListener('load',fit);setTimeout(fit,50);document.fonts&&document.fonts.ready.then(fit);})();
